import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-D1NZeQ-i.js";var i=JSON.parse(`{"path":"/router/routeros/h3ab9wo3/","title":"PVE下安装系统 | RouterOS","lang":"zh-CN","frontmatter":{"title":"PVE下安装系统","createTime":"2026/08/25 13:51:48","permalink":"/router/routeros/h3ab9wo3/","copyright":{"creation":"reprint","license":"CC-BY-4.0","source":"https://gitee.com/callmer/routeros_toss_notes/tree/master","author":{"name":"callmer","url":"https://gitee.com/callmer"}}},"readingTime":{"minutes":8.1,"words":2429},"git":{},"filePathRelative":"router/routeros/00.PVE下安装系统.md","headers":[]}`),a={name:`00.PVE下安装系统.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="_0-前期准备" tabindex="-1"><a class="header-anchor" href="#_0-前期准备"><span>0.前期准备</span></a></h2><p>一台工作正常的 PVE 服务器， PVE 安装与配置方法参考我的系列文章 <a href="https://gitee.com/callmer/pve_toss_notes" target="_blank" rel="noopener noreferrer">Proxmox VE 折腾手记</a> 。</p><p>一台已经联网的 <code>前置路由器</code> 或 <code>光猫</code> ，用于 RouterOS 系统激活。</p><p>访问 RouterOS 的官网 <a href="https://mikrotik.com/download/chr" target="_blank" rel="noopener noreferrer">Mikrotik</a> 下载最新的 Winbox 软件、RouterOS 镜像以及镜像文件对应的校验信息。</p><h3 id="winbox" tabindex="-1"><a class="header-anchor" href="#winbox"><span>Winbox:</span></a></h3><p>根据所使用的操作系统类型，下载合适的 Winbox 客户端软件。</p><p><img src="/images/router/routeros/p00/dl_winbox.jpg" alt="下载Winbox" width="2546" height="1770"></p><h3 id="routeros-镜像" tabindex="-1"><a class="header-anchor" href="#routeros-镜像"><span>RouterOS 镜像:</span></a></h3><p>PVE 中运行 RouterOS 需要 <code>.img</code> 格式的镜像，因此选择 <code>RAW disk</code> 。</p><p><img src="/images/router/routeros/p00/dl_ros.jpg" alt="下载RouterOS" width="2546" height="1468"></p><h2 id="_1-创建-routeros-虚拟机" tabindex="-1"><a class="header-anchor" href="#_1-创建-routeros-虚拟机"><span>1.创建 RouterOS 虚拟机</span></a></h2><h3 id="_1-1-常规" tabindex="-1"><a class="header-anchor" href="#_1-1-常规"><span>1.1.常规</span></a></h3><p>登录到 PVE 后台后，进入新建虚拟机流程，并打开底部 <code>高级</code> 选项。</p><p><code>节点</code> 选择当前设备，<code>VM ID</code> 和 <code>名称</code> 可自定义。</p><p><code>启动/关机顺序</code> 和 <code>启动延时</code> 可按需调整。</p><p><img src="/images/router/routeros/p00/ros_pve_init.jpg" alt="虚拟机-常规" width="1138" height="854"></p><h3 id="_1-2-操作系统" tabindex="-1"><a class="header-anchor" href="#_1-2-操作系统"><span>1.2.操作系统</span></a></h3><p>操作系统 <code>类别</code> 选择 <code>Linux</code> 、内核 <code>版本</code> 选择 <code>7.x - 2.6 Kernel</code> 即可，且无需使用引导介质。</p><p><img src="/images/router/routeros/p00/ros_pve_guestos.jpg" alt="虚拟机-操作系统" width="1138" height="854"></p><h3 id="_1-3-系统" tabindex="-1"><a class="header-anchor" href="#_1-3-系统"><span>1.3.系统</span></a></h3><p><code>显卡</code> 选择 <code>默认</code> ，<code>机型</code> 选择 <code>q35</code> ，对 <code>PCIE</code> 直通设备有更好的支持。</p><p>新版的 RouterOS 对 <code>Qemu Agent</code> 支持良好，因此建议勾选 <code>Qemu 代理</code> 选项。</p><p>如果后续使用过程中 RouterOS <strong>不稳定</strong> ，请保持 <code>机型</code> 选择 <code>默认 (i440fx)</code> 。</p><p><img src="/images/router/routeros/p00/ros_pve_os.jpg" alt="虚拟机-系统" width="1138" height="854"></p><h3 id="_1-4-磁盘" tabindex="-1"><a class="header-anchor" href="#_1-4-磁盘"><span>1.4.磁盘</span></a></h3><p>后续将导入 RouterOS 镜像文件并生成磁盘，因此移除所有自动添加的磁盘。</p><p><img src="/images/router/routeros/p00/ros_pve_hd.jpg" alt="虚拟机-磁盘" width="1138" height="854"></p><h3 id="_1-5-cpu" tabindex="-1"><a class="header-anchor" href="#_1-5-cpu"><span>1.5.CPU</span></a></h3><p>请根据物理设备 CPU 资源使用情况来分配 RouterOS CPU 资源。</p><p>CPU <code>类型</code> 选择 <code>host</code> ，<code>核心</code> 根据物理 CPU 核心数进行酌情设置。</p><p>如果设备有多路 CPU 推荐启用 <strong>NUMA</strong> 。</p><p>如果设备 CPU <strong>超分（Over-Commit）</strong> 比较严重，可适当将 <code>CPU 权重</code> 参数翻倍，让 RouterOS 获得更多的 CPU 时间。</p><p><img src="/images/router/routeros/p00/ros_pve_cpu.jpg" alt="虚拟机-CPU" width="1138" height="854"></p><h3 id="_1-6-内存" tabindex="-1"><a class="header-anchor" href="#_1-6-内存"><span>1.6.内存</span></a></h3><p>内存一般 <code>2048MiB</code> 足够使用，MikroTik 官方给出的 CHR 最低要求是 <code>256MiB</code> ，但建议至少分配 <code>1024MiB</code> 。</p><p><img src="/images/router/routeros/p00/ros_pve_mem.jpg" alt="虚拟机-内存" width="1138" height="854"></p><h3 id="_1-7-网络" tabindex="-1"><a class="header-anchor" href="#_1-7-网络"><span>1.7.网络</span></a></h3><p>需要注意，当前页面只能设置单个网络设备，而网络设备的添加顺序将和 RouterOS 内部显示的网卡顺序一致。</p><p>因此，先仅添加 <code>WAN</code> 对应的网口（ 此处为 <code>vmbr0</code> ），<code>型号</code> 选择 <code>VirtIO (半虚拟化)</code> ，并取消勾选 <code>防火墙</code> 选项。</p><p>对于使用硬件直通的小伙伴，可根据实际情况来修改此处网络设备选项。</p><p>推荐在 <strong>Multiqueue</strong> 处根据前面设置的 CPU 数量进行网卡多队列设置，设置比例为 1:1 。</p><p>即有 n 个 CPU 核心，此处多队列也设置为 n 。</p><p><img src="/images/router/routeros/p00/ros_pve_eths.jpg" alt="虚拟机-网络" width="1138" height="854"></p><p>根据官方文档中对 <code>Multiqueue</code> 的描述：</p><p><img src="/images/router/routeros/p00/ros_pve_eths_multiqueue.png" alt="虚拟机-网络-网卡多队列" width="1280" height="445"></p><p>因此，对于使用 <code>VirtIO</code> 网卡的虚拟机，特别是作为路由器使用且需处理大量带宽时，可以在一定程度上提高其网络吞吐性能。</p><p>但 RouterOS v6 版本对 <code>Multiqueue</code> 可能未良好支持，因此建议 RouterOS v7 及以上版本开启该选项。</p><h3 id="_1-8-确认" tabindex="-1"><a class="header-anchor" href="#_1-8-确认"><span>1.8.确认</span></a></h3><p>接下来查看设置总览，确认无误后，即可点击 <code>完成</code> 。</p><p><img src="/images/router/routeros/p00/ros_pve_confirm.jpg" alt="虚拟机-确认" width="1138" height="854"></p><h2 id="_2-调整网络设备" tabindex="-1"><a class="header-anchor" href="#_2-调整网络设备"><span>2.调整网络设备</span></a></h2><p>此时，查看虚拟机详情页，可以看到刚创建好的虚拟机。</p><p><img src="/images/router/routeros/p00/ros_hw_review.jpg" alt="虚拟机参数" width="1280" height="640"></p><p>去掉 CD/DVD 驱动器后，开始添加网络设备。</p><p><img src="/images/router/routeros/p00/ros_add_eths.jpg" alt="虚拟机添加网卡" width="902" height="388"></p><p>重复添加网络设备，去掉防火墙，并增加网卡多队列参数后，示例如下：</p><p><img src="/images/router/routeros/p00/ros_add_eths_done.jpg" alt="虚拟机添加网卡完成" width="1280" height="640"></p><h2 id="_3-添加-virtio-rng" tabindex="-1"><a class="header-anchor" href="#_3-添加-virtio-rng"><span>3.添加 VirtIO RNG</span></a></h2><p>为确保系统拥有充足的可用熵，需为 RouterOS 虚拟机添加 <code>VirtIO RNG</code> 熵源。</p><p>点击顶部 <code>新增</code> 菜单，选择 <code>VirtIO RNG</code> 。</p><p><img src="/images/router/routeros/p00/pve_add_rng.jpg" alt="添加RNG" width="1280" height="640"></p><p><code>熵源</code> 选择 <code>/dev/urandom</code> ，其余参数保持默认即可。</p><p><img src="/images/router/routeros/p00/pve_add_rng_details.jpg" alt="RNG参数" width="1280" height="640"></p><h2 id="_4-创建-routeros-系统盘" tabindex="-1"><a class="header-anchor" href="#_4-创建-routeros-系统盘"><span>4.创建 RouterOS 系统盘</span></a></h2><h3 id="_4-1-获取镜像文件" tabindex="-1"><a class="header-anchor" href="#_4-1-获取镜像文件"><span>4.1.获取镜像文件</span></a></h3><p>使用终端工具登录到 PVE 服务器，在 <code>/tmp</code> 目录中创建一个目录用于下载 RouterOS 镜像文件。</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;"><pre class="shiki shiki-themes light-plus dark-plus vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">## 创建并进入目录</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">$</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> mkdir</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -p</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> /tmp/RouterOS</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> &amp;&amp; </span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">cd</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> /tmp/RouterOS</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">## 下载 RouterOS 镜像校验文件</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">$</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> curl</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -LR</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -O</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> https://download.mikrotik.com/routeros/7.21.5/chr-7.21.5.img.zip.sha256</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">## 下载 RouterOS 镜像文件</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">$</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> curl</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -LR</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -O</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> https://download.mikrotik.com/routeros/7.21.5/chr-7.21.5.img.zip</span></span></code></pre></div><p>镜像文件下载完成后，使用官方提供的校验文件验证镜像完整性。</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;"><pre class="shiki shiki-themes light-plus dark-plus vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">## 检查文件是否存在</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">$</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> ls</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -lah</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">## 执行镜像文件校验</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">$</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> sha256sum</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> --check</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> chr-7.21.5.img.zip.sha256</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">#### 镜像校验成功示例输出</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">chr-7.21.5.img.zip:</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> OK</span></span></code></pre></div><p>由于镜像文件为 <code>zip</code> 压缩格式，无法直接使用，因此需要对其解压缩，执行以下命令，解压出 <code>.img</code> 格式镜像。</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;"><pre class="shiki shiki-themes light-plus dark-plus vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">## 将镜像文件解压缩</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">$</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> python3</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -m</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> zipfile</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -e</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> chr-7.21.5.img.zip</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &quot;$(</span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">pwd</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">)&quot;</span></span></code></pre></div><h3 id="_4-2-导入镜像文件" tabindex="-1"><a class="header-anchor" href="#_4-2-导入镜像文件"><span>4.2.导入镜像文件</span></a></h3><p>在创建 RouterOS 虚拟机时，曾指定了 <code>VM ID</code>，使用该 <code>VM ID</code> 将 RouterOS 镜像导入 PVE 系统，演示中为 <strong><code>101</code></strong> 。</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;"><pre class="shiki shiki-themes light-plus dark-plus vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">## 将 img 镜像导入虚拟机中</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">$</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> qm</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> importdisk</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 101</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> chr-7.21.5.img</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> local-lvm</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">#### img 镜像导入示例输出</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">unused0:</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> successfully</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> imported</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> disk</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &#39;local-lvm:vm-101-disk-0&#39;</span></span></code></pre></div><h3 id="_4-3-调整虚拟机磁盘设置" tabindex="-1"><a class="header-anchor" href="#_4-3-调整虚拟机磁盘设置"><span>4.3.调整虚拟机磁盘设置</span></a></h3><p>磁盘导入成功后，虚拟机硬件列表中将显示一块未使用的磁盘设备，可鼠标 <strong>双击</strong> 该设备进行配置调整。</p><p><img src="/images/router/routeros/p00/ros_hd_use.jpg" alt="启用磁盘" width="1280" height="640"></p><p>当宿主机使用 SSD 作为物理存储设备，并且虚拟磁盘采用 Thin Provisioning （精简置备）模式时，可考虑开启以下选项：</p><ul><li><p><code>丢弃</code> （ <code>Discard</code> ） 选项，有助于存储空间回收。</p></li><li><p><code>SSD 仿真</code> （ <code>SSD Emulation</code> ） 选项，让虚拟机将虚拟磁盘视为 SSD 存储设备。</p></li></ul><p>在弹出的对话框中，确认 <code>IO thread</code> 选项为 <strong>勾选</strong> 状态，并点击 <code>新增</code> 。</p><p><img src="/images/router/routeros/p00/ros_hd_iothread.jpg" alt="调整磁盘参数" width="1280" height="640"></p><p>导入的镜像仅具备 <code>128MiB</code> 磁盘空间，为方便后续使用，可通过 <code>qm</code> 命令直接将该磁盘调整至目标容量。</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;"><pre class="shiki shiki-themes light-plus dark-plus vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">## 将镜像容量设置为 2G</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">$</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> qm</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> disk</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> resize</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 101</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> scsi0</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 2G</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">#### 镜像扩容示例输出</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">  Size</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> of</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> logical</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> volume</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> pve/vm-101-disk-0</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> changed</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> from</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 128.00</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> MiB</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> (32 </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">extents</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">) to 2.00 GiB (</span><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">512</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> extents</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">).</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">  Logical</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> volume</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> pve/vm-101-disk-0</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> successfully</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> resized.</span></span></code></pre></div><p>或 <strong>单击</strong> 选中该磁盘，然后使用 <code>磁盘操作</code> 菜单中的 <code>调整大小</code> 选项对磁盘镜像进行扩容。</p><p><img src="/images/router/routeros/p00/ros_hd_resize.jpg" alt="磁盘扩容-2" width="1280" height="640"></p><p>本文作为演示，在弹出的对话框中，给该磁盘仅增加 <code>1.875GiB</code> 磁盘空间。</p><p><img src="/images/router/routeros/p00/ros_hd_add1G.jpg" alt="磁盘扩容-3" width="1280" height="640"></p><p>镜像磁盘扩容后，在虚拟机 <strong>初次启动</strong> 时，RouterOS 会根据磁盘空间自动扩容内部文件系统。</p><p><img src="/images/router/routeros/p00/ros_hd_finish.jpg" alt="磁盘扩容-4" width="1280" height="640"></p><h2 id="_5-创建-routeros-日志盘" tabindex="-1"><a class="header-anchor" href="#_5-创建-routeros-日志盘"><span>5.创建 RouterOS 日志盘</span></a></h2><p>RouterOS 的日志一般记录在内存中，当系统重启后，历史日志将会丢失。</p><p>而使用附加硬盘来记录 RouterOS 的日志，可在系统意外重启时看到历史日志，方便追溯问题。</p><p>点击顶部 <code>新增</code> ，选择 <code>硬盘</code> ：</p><p><img src="/images/router/routeros/p00/pve_add_hd.jpg" alt="PVE添加硬盘" width="1280" height="640"></p><p><code>总线/设备</code> 选择 <code>SCSI</code> ，设备编号 PVE 会自动设置，演示中为 <code>1</code> 。</p><p><code>磁盘大小</code> 根据 PVE 服务器资源剩余情况酌情设置，演示为 <code>1GiB</code> 。</p><p><img src="/images/router/routeros/p00/pve_add_hd_details.jpg" alt="PVE添加硬盘参数" width="1280" height="640"></p><p>日志盘添加完成后，如图所示。</p><p><img src="/images/router/routeros/p00/pve_add_hd_done.jpg" alt="PVE添加硬盘完成" width="1280" height="640"></p><h2 id="_6-调整虚拟机配置参数" tabindex="-1"><a class="header-anchor" href="#_6-调整虚拟机配置参数"><span>6.调整虚拟机配置参数</span></a></h2><p>初创的 RouterOS 的配置参数如下，需要进一步调整的参数包括：</p><ul><li>开机自启动（建议在 RouterOS 完全设置好之后再修改）</li><li>启动/关机顺序（建议在 RouterOS 完全设置好之后再修改）</li><li>引导顺序</li><li>使用平板指针</li></ul><p><img src="/images/router/routeros/p00/ros_vm_origin.jpg" alt="ROS虚拟机原始参数" width="1280" height="778"></p><h3 id="_6-1-设置开机自启动" tabindex="-1"><a class="header-anchor" href="#_6-1-设置开机自启动"><span>6.1.设置开机自启动</span></a></h3><p>开机自启动设置为 “是” ，启动顺序推荐如下：</p><ul><li><code>启动/关机顺序</code> 为 <code>1</code> ，表示该虚拟机第一个启动，最后一个关机</li><li><code>启动延时</code> 为 <code>15</code> ，表示该虚拟机启动后，延迟 <code>15</code> 秒再启动下一个虚拟机</li></ul><p><img src="/images/router/routeros/p00/ros_vm_autostart.jpg" alt="ROS开机自启动" width="1280" height="778"></p><h3 id="_6-2-修改引导顺序" tabindex="-1"><a class="header-anchor" href="#_6-2-修改引导顺序"><span>6.2.修改引导顺序</span></a></h3><p>在 <code>net0</code> 设备处，<strong>取消勾选</strong> “已启用” 复选框。</p><p>在 <code>scsi0</code> 设备处勾选 “已启用” 复选框，并通过排序功能将其拖拽至首位，点击 <code>确定</code> 即可。</p><p><img src="/images/router/routeros/p00/ros_vm_boot.jpg" alt="ROS引导项" width="1280" height="778"></p><h3 id="_6-3-修改平板指针设置" tabindex="-1"><a class="header-anchor" href="#_6-3-修改平板指针设置"><span>6.3.修改平板指针设置</span></a></h3><p>关闭 <code>使用平板指针</code> 选项，可以一定程度上降低虚拟机的 CPU 使用率。</p><p><img src="/images/router/routeros/p00/ros_vm_tablet.jpg" alt="ROS虚拟机关闭平板指针" width="1280" height="778"></p><p>修改完成后，总体情况如下，等待 RouterOS 完全配置好，运行无异常之后，即可开启该虚拟机的 <code>开机自启动</code> 选项。</p><p><img src="/images/router/routeros/p00/ros_vm_finish.jpg" alt="ROS虚拟机参数调整完成" width="1280" height="778"></p><h3 id="_6-4-设置虚拟机备注信息" tabindex="-1"><a class="header-anchor" href="#_6-4-设置虚拟机备注信息"><span>6.4.设置虚拟机备注信息</span></a></h3><p>进入左侧虚拟机 <code>概要</code> 页面，修改虚拟机的备注信息。</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#000000;--shiki-dark:#D4D4D4;--shiki-light-bg:#FFFFFF;--shiki-dark-bg:#1E1E1E;"><pre class="shiki shiki-themes light-plus dark-plus vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;">### 服务器信息</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">-</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 系统：</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> RouterOS</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">-</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 用途：</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 主路由系统</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">-</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 自启：</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 是</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">-</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 用户：</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> admin</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> ( </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">只读</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> )</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">-</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 用户：</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> fox</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> ( </span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">管理</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"> )</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">-</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> IPv4：</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> 172.16.1.1/24</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">-</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> IPv6：</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> DHCPv6</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> Client</span></span></code></pre></div><p><img src="/images/router/routeros/p00/ros_vm_notes.jpg" alt="ROS虚拟机备注" width="1740" height="600"></p><h2 id="_7-虚拟机开机" tabindex="-1"><a class="header-anchor" href="#_7-虚拟机开机"><span>7.虚拟机开机</span></a></h2><p>接下来检验 RouterOS 虚拟机是否能正常启动，切换至虚拟机的 <code>控制台</code> 选项卡即可开机。</p><p>当前 RouterOS 尚未进行任何配置，不会对现有网络环境造成影响，但需留意后续配置细节：若 RouterOS 设置了内部网络接口桥接，而 PVE 环境中已有其他路由系统（例如 OPNsense 防火墙）在相同网络接口上启用桥接功能，可能会引发网络环路，导致网络无法正常访问。</p><p>待虚拟机启动后，若控制台显示如图所示内容，即表明 RouterOS 已安装成功。</p><p><img src="/images/router/routeros/p00/ros_login.jpg" alt="ROS登录" width="1280" height="640"></p><p>RouterOS 的默认账户为 <code>admin</code> ，无需密码即可登录。</p><p><img src="/images/router/routeros/p00/ros_vm_ok.jpg" alt="ROS安装完成" width="3294" height="1790"></p><p>至此，RouterOS 虚拟机安装步骤完成。</p>`,128)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};